import java.util.Scanner;

public class ProblemE {

	public static final long M = 998244353;

	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);
		long m = sc.nextLong();
		long n = sc.nextLong();
		long l = sc.nextLong();
		long r = sc.nextLong();
		sc.close();

		long total = m * n;
		long segmentSize = r - l + 1;

		long result = fastExponentiation(segmentSize, total);
		if (total % 2 == 1) {
			System.out.println(result);
		} else {
			if (segmentSize % 2 == 0)
				System.out.println((result * modularInverse(2, M)) % M);
			else
				System.out.println(((result + 1) % M * modularInverse(2, M)) % M);
		}
	}

	public static long fastExponentiation(long base, long exponent) {
		long res = 1;
		long mod = M;
		while (exponent > 0) {
			if ((exponent & 1) == 1) {
				res = (res * base) % mod;
			}
			base = (base * base) % mod;
			exponent >>= 1;
		}
		return res;
	}

	public static long modularInverse(long a, long m) {
		return fastExponentiation(a, m - 2);
	}
}
